mermaid_diagrams.diagram_code:
graph TD
    subgraph Macrocycle [Annual Plan (e.g., 1 Year)]
        M1(Mesocycle 1: Preparatory) --> M2(Mesocycle 2: Competitive);
        M2 --> M3(Mesocycle 3: Preparatory);
        M3 --> M4(Mesocycle 4: Competitive);
        M4 --> M5(Mesocycle 5: Transition/Deload);
    end

    subgraph M2 [Mesocycle: Competitive Phase (e.g., 4-Week Project)]
        W1(Week 1: Build-Up) --> W2(Week 2: Peak Load);
        W2 --> W3(Week 3: Peak Load);
        W3 --> W4(Week 4: Taper/Deliver);
    end

    subgraph W2 [Microcycle: Peak Load Week]
        Day1(Mon: Hard / 3 Sprints) --> Day2(Tue: Medium / 2 Sprints);
        Day2 --> Day3(Wed: Hard / 3 Sprints);
        Day3 --> Day4(Thu: Medium / 2 Sprints);
        Day4 --> Day5(Fri: Light / 1 Sprint + Planning);
    end
